services = list_services()
results = for svc in services {
    res = boundary retry 2 { return search_logs({ service: svc, level: "ERROR", page: 1 }) } catch err {
        return fail("SEARCH_FAILED", svc + ": " + err.message)
    }
    return { service: svc, total_errors: res.total_items, total_pages: res.total_pages,
             first_ts: res.items[0].ts if res.items != [] else null,
             last_ts_page1: res.items[list.length(res.items) - 1].ts if res.items != [] else null }
}
return results

