p1 = boundary retry 2 { return search_logs({ service: "payments", level: "ERROR", page: 1 }) } catch err {
    return fail("LOG_P1_FAILED", err.code + ": " + err.message)
}
p2 = boundary retry 2 { return search_logs({ service: "payments", level: "ERROR", page: 2 }) } catch err {
    return fail("LOG_P2_FAILED", err.code + ": " + err.message)
}
deploys = boundary retry 2 { return get_deploys({ service: "payments" }) } catch err {
    return fail("DEPLOYS_FAILED", err.code + ": " + err.message)
}
owner = boundary retry 2 { return get_service_owners({ service: "payments" }) } catch err {
    return fail("OWNER_FAILED", err.code + ": " + err.message)
}
all_logs = p1.items + p2.items
timestamps = for item in all_logs { return item.ts }
return { timestamps, messages_sample: [all_logs[0].message, all_logs[list.length(all_logs) - 1].message], deploys, owner }
